    constructor(private route: ActivatedRoute) {}

    ngOnInit(): void {
        const mallId = this.route.snapshot.paramMap.get('id');
        if (mallId) {
            this.loadMallDetails(mallId);
            this.loadShops(mallId);
        }
    }

